import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  users: defineTable({
    name: v.string(),
  }),
  posts: defineTable({
    title: v.string(),
    content: v.string(),
    author_id: v.id("users"),
  }),
  tags: defineTable({
    name: v.string(),
  }),
  post_tags: defineTable({
    post_id: v.id("posts"),
    tag_id: v.id("tags"),
  }),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const createUser = mutation({
  args: { name: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db.insert("users", { name: args.name });
  },
});

export const createPost = mutation({
  args: { title: v.string(), content: v.string(), author_id: v.id("users") },
  handler: async (ctx, args) => {
    return await ctx.db.insert("posts", {
      title: args.title,
      content: args.content,
      author_id: args.author_id,
    });
  },
});

export const createTag = mutation({
  args: { name: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db.insert("tags", { name: args.name });
  },
});

export const assignTag = mutation({
  args: { post_id: v.id("posts"), tag_id: v.id("tags") },
  handler: async (ctx, args) => {
    return await ctx.db.insert("post_tags", {
      post_id: args.post_id,
      tag_id: args.tag_id,
    });
  },
});

export const getUsersWithPosts = query({
  handler: async (ctx) => {
    const users = await ctx.db.query("users").collect();
    const usersWithPosts = await Promise.all(
      users.map(async (user) => {
        const posts = await ctx.db
          .query("posts")
          .filter((q) => q.eq(q.field("author_id"), user._id))
          .collect();
        return { ...user, posts };
      })
    );
    return usersWithPosts;
  },
});

export const getPostsWithTags = query({
  handler: async (ctx) => {
    const posts = await ctx.db.query("posts").collect();
    const postsWithDetails = await Promise.all(
      posts.map(async (post) => {
        const author = await ctx.db.get(post.author_id);
        const postTags = await ctx.db
          .query("post_tags")
          .filter((q) => q.eq(q.field("post_id"), post._id))
          .collect();
        const tags = await Promise.all(
          postTags.map(async (pt) => {
            return await ctx.db.get(pt.tag_id);
          })
        );
        return { ...post, author, tags: tags.filter(Boolean) };
      })
    );
    return postsWithDetails;
  },
});

export const getTags = query({
  handler: async (ctx) => {
    return await ctx.db.query("tags").collect();
  },
});

export const getUsers = query({
  handler: async (ctx) => {
    return await ctx.db.query("users").collect();
  },
});

import { useState } from 'react'
import { useQuery, useMutation } from "convex/react";
import { api } from "../convex/_generated/api";
import { Id } from "../convex/_generated/dataModel";

function App() {
  const users = useQuery(api.db.getUsers) || [];
  const tags = useQuery(api.db.getTags) || [];
  const posts = useQuery(api.db.getPostsWithTags) || [];

  const createUser = useMutation(api.db.createUser);
  const createPost = useMutation(api.db.createPost);
  const createTag = useMutation(api.db.createTag);
  const assignTag = useMutation(api.db.assignTag);

  const [userName, setUserName] = useState('');
  const [postTitle, setPostTitle] = useState('');
  const [postContent, setPostContent] = useState('');
  const [selectedUserId, setSelectedUserId] = useState<string>('');

  const [tagName, setTagName] = useState('');

  const [selectedPostId, setSelectedPostId] = useState<string>('');
  const [selectedTagId, setSelectedTagId] = useState<string>('');

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName) return;
    await createUser({ name: userName });
    setUserName('');
  };

  const handleCreatePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!postTitle || !postContent || !selectedUserId) return;
    await createPost({ 
      title: postTitle, 
      content: postContent, 
      author_id: selectedUserId as Id<"users"> 
    });
    setPostTitle('');
    setPostContent('');
  };

  const handleCreateTag = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tagName) return;
    await createTag({ name: tagName });
    setTagName('');
  };

  const handleAssignTag = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPostId || !selectedTagId) return;
    await assignTag({ 
      post_id: selectedPostId as Id<"posts">, 
      tag_id: selectedTagId as Id<"tags"> 
    });
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Convex 1:N and N:M Relationships</h1>

      <section>
        <h2>Create User</h2>
        <form onSubmit={handleCreateUser}>
          <input 
            data-testid="create-user-input"
            value={userName} 
            onChange={(e) => setUserName(e.target.value)} 
            placeholder="User Name" 
          />
          <button type="submit" data-testid="submit-user-btn">Create User</button>
        </form>
      </section>

      <section>
        <h2>Create Post</h2>
        <form onSubmit={handleCreatePost}>
          <select 
            value={selectedUserId} 
            onChange={(e) => setSelectedUserId(e.target.value)}
          >
            <option value="">Select Author</option>
            {users.map(user => (
              <option key={user._id} value={user._id}>{user.name}</option>
            ))}
          </select>
          <input 
            value={postTitle} 
            onChange={(e) => setPostTitle(e.target.value)} 
            placeholder="Post Title" 
          />
          <input 
            value={postContent} 
            onChange={(e) => setPostContent(e.target.value)} 
            placeholder="Post Content" 
          />
          <button type="submit">Create Post</button>
        </form>
      </section>

      <section>
        <h2>Create Tag</h2>
        <form onSubmit={handleCreateTag}>
          <input 
            value={tagName} 
            onChange={(e) => setTagName(e.target.value)} 
            placeholder="Tag Name" 
          />
          <button type="submit">Create Tag</button>
        </form>
      </section>

      <section>
        <h2>Assign Tag to Post</h2>
        <form onSubmit={handleAssignTag}>
          <select 
            value={selectedPostId} 
            onChange={(e) => setSelectedPostId(e.target.value)}
          >
            <option value="">Select Post</option>
            {posts.map(post => (
              <option key={post._id} value={post._id}>{post.title}</option>
            ))}
          </select>
          <select 
            value={selectedTagId} 
            onChange={(e) => setSelectedTagId(e.target.value)}
          >
            <option value="">Select Tag</option>
            {tags.map(tag => (
              <option key={tag._id} value={tag._id}>{tag.name}</option>
            ))}
          </select>
          <button type="submit">Assign Tag</button>
        </form>
      </section>

      <section>
        <h2>Posts List</h2>
        <ul>
          {posts.map(post => (
            <li key={post._id} data-testid="post-item">
              <strong>{post.title}</strong> by {post.author?.name}
              <p>{post.content}</p>
              <div>
                Tags: {post.tags.map(tag => tag?.name).join(', ')}
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

export default App;

